 public class PdfBridge {
 @JavascriptInterface public void ready(){runOnUiThread(()->{if(trusted(web.getUrl()))dismissSplash();});}
  @JavascriptInterface public void sharePdf(String name,String encoded){runOnUiThread(()->{if(!trusted(web.getUrl())||encoded==null||encoded.length()>28000000)return;new Thread(()->{try{byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);if(bytes.length<5||!new String(bytes,0,5,"US-ASCII").equals("%PDF-"))throw new IOException();String safe=(name==null?"Workshop-Desk.pdf":name).replaceAll("[^a-zA-Z0-9._-]","_");if(!safe.endsWith(".pdf"))safe+=".pdf";File dir=new File(getCacheDir(),"pdf");dir.mkdirs();File f=new File(dir,System.currentTimeMillis()+"-"+safe);try(FileOutputStream out=new FileOutputStream(f)){out.write(bytes);}Uri uri=Uri.parse("content://in.workshopdesk.app.pdf/"+Uri.encode(f.getName()));Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("application/pdf");intent.putExtra(Intent.EXTRA_STREAM,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("PDF",uri));runOnUiThread(()->startActivity(Intent.createChooser(intent,"Share or save PDF")));}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"Could not share PDF",Toast.LENGTH_LONG).show());}}).start();});}
  @JavascriptInterface public void printPage(){runOnUiThread(()->{if(trusted(web.getUrl()))((PrintManager)getSystemService(PRINT_SERVICE)).print("Workshop Desk",web.createPrintDocumentAdapter("Workshop Desk"),null);});}
 }
 private void dismissSplash(){if(splash!=null){splash.setVisibility(View.GONE);if(splash instanceof WebView)((WebView)splash).destroy();splash=null;}loadingHandler.removeCallbacksAndMessages(null);}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private void fullScreen(){if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);android.view.WindowInsetsController controller=getWindow().getInsetsController();if(controller!=null){controller.hide(android.view.WindowInsets.Type.statusBars()|android.view.WindowInsets.Type.navigationBars());controller.setSystemBarsBehavior(android.view.WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);}
 @Override public void onWindowFocusChanged(boolean hasFocus){super.onWindowFocusChanged(hasFocus);if(hasFocus)fullScreen();}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setTitle("Close Workshop Desk?").setPositiveButton("Close",(d,w)->finish()).setNegativeButton("Stay",null).show();}
 @Override protected void onSaveInstanceState(Bundle b){web.saveState(b);super.onSaveInstanceState(b);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}}
 @Override protected void onDestroy(){loadingHandler.removeCallbacksAndMessages(null);web.removeJavascriptInterface("WorkshopAndroid");web.destroy();super.onDestroy();}
